content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-19-photo-album-007

=== 用户原始指令 (query.txt) ===
做一张以图为主的卡,数字会动,点一下能导航,日历上的事能看到,红色提醒我注意

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做一张以图为主的卡,数字会动,点一下能导航,日历上的事能看到,红色提醒我注意",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "cal_evt_001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "eventCountText": {
          "type": "string",
          "description": "今日日历事件数量展示文本，用于动态数字主显示。",
          "sampleValue": "2"
        },
        "alertText": {
          "type": "string",
          "description": "需要用户注意的日程提醒短文本。",
          "sampleValue": "重要提醒"
        },
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程项唯一标识符，用于跳转查看日程详情。",
              "sampleValue": "cal_evt_001"
            },
            "title": {
              "type": "string",
              "description": "日程标题。",
              "sampleValue": "相册整理提醒"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间，今日事件使用 HH:MM 展示。",
              "sampleValue": "09:15"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间，今日事件使用 HH:MM 展示。",
              "sampleValue": "10:00"
            },
            "eventLocation": {
              "type": "string",
              "description": "日程地点或关联位置。",
              "sampleValue": "云相册"
            }
          }
        ]
      }
    },
    "ui": {
      "actionLabel": {
        "type": "string",
        "description": "进入日程详情的按钮文案。",
        "sampleValue": "查看详情"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合用于日程管理、日历事件查看和当日安排的主视觉识别。"
    }
  ]
}

